  const items=t.items??[];
  const tax=t.tax??0;
  const subtotal=t.subtotal??0;
  const total=t.total??0;
  const tip=t.tip??0;
  const isDelivery=t.type==="delivery";
  const sizeMap={"SM":"Sm","GF Small":"GF Sm","MED":"Med","LRG":"Lrg","XL":"XtrLrg"};
  const now=new Date();
  const ordered=t.createdAt?new Date(t.createdAt):now;
  const promisedMs=ordered.getTime()+(t.estimatedMinutes||30)*60000;
  const promised=new Date(promisedMs);
  const fmt=d=>d.toLocaleTimeString([],{hour:"2-digit",minute:"2-digit",hour12:true}).replace(" ","").toLowerCase();
  const fmtDate=d=>{const m=d.getMonth()+1,dy=d.getDate(),y=d.getFullYear();return`${m}/${dy}/${y}`;};
  const money=n=>(+n).toFixed(2);
  const pad=(s,w)=>{s=String(s);return s.length>=w?s:s+' '.repeat(w-s.length);};
  const padL=(s,w)=>{s=String(s);return s.length>=w?s:' '.repeat(w-s.length)+s;};
  const W=42;
  const center=s=>{ const sp=Math.max(0,Math.floor((W-s.length)/2)); return ' '.repeat(sp)+s; };
  const rule='-'.repeat(W);

  // Parse delivery address & notes from notes field
  let addr=null,notes=null;
  if(t.notes?.startsWith("DELIVERY:")){
    const rest=t.notes.replace(/^DELIVERY:\s*/,"");
    const parts=rest.split(" | ");
    addr=parts[0];
    notes=parts.slice(1).join(" | ")||null;
  } else { notes=t.notes||null; }

  let lines=[];
  lines.push(center("Prep Ticket"));
  lines.push(center("*".repeat(20)));
  lines.push(center(`Order: ${t.orderNumber||t.id}`));
  lines.push("+-----------------------------------------+");
  lines.push("|                                         |");
  lines.push("+-----------------------------------------+");
  lines.push("Stratos Pizzeria & Restaurant");
  lines.push("20018 Loyalist Parkway");
  lines.push("Consecon         ON   KOK1t0");
  lines.push("");
  const orderType=isDelivery?"Delivery":"Pick Up";
  lines.push(pad(orderType,16)+fmtDate(ordered));
  lines.push(`  Time Ordered: ${fmt(ordered)}`);
  lines.push(`  Time Promised: ${fmt(promised)}`);
  lines.push("");
  if(t.customerName) lines.push(`  ${t.customerName}`);
  if(t.customerPhone) lines.push(`  ${t.customerPhone}`);
  if(addr) lines.push(`  ${addr}`);
  if(notes) lines.push(`--${notes}`);
  lines.push(rule);
  lines.push("");

  // Line items
  items.forEach(item=>{
    let mods=[];
    try{ mods=JSON.parse(item.modifiers||"[]"); }catch{}
    // Parse size from modifiers for pizza
    let sizePfx="";
    const sizeModIdx=mods.findIndex(m=>Object.keys(sizeMap).some(k=>m.startsWith(k)));
    if(sizeModIdx>=0){
      const rawSize=mods[sizeModIdx];
      const key=Object.keys(sizeMap).find(k=>rawSize.startsWith(k));
      if(key){ sizePfx=sizeMap[key]+" "; mods=mods.filter((_,i)=>i!==sizeModIdx); }
    }
    const itemName=sizePfx+(item.name||"");
    const qty=item.quantity||1;
    const itemPrice=money((item.price||0)*qty);
    const qtyStr=pad(String(qty),2);
    const nameStr=pad(itemName,26);
    lines.push(`${qtyStr} ${nameStr} ${padL(itemPrice,7)}`);
    // Modifiers indented
    mods.forEach(mod=>{
      if(!mod) return;
      const isRemove=mod.toLowerCase().startsWith("no ");
      const label=pad("  "+mod,30);
      lines.push(`   ${label}`);
    });
  });

  lines.push("");
  lines.push(rule);
  lines.push(pad("  Subtotal",32)+padL(money(subtotal),8));
  lines.push(pad("  Tax",32)+padL(money(tax),8));
  lines.push(pad("  Delivery Chg",32)+padL(isDelivery?"TBD":"0.00",8));
  lines.push(pad("  Amount Due",32)+padL(money(total),8));
  lines.push("");
  lines.push("  Tip  "+"-".repeat(28));
  lines.push("");
  lines.push("  Total Amount  "+"-".repeat(22));
  lines.push("");
  lines.push(pad("  Total Discount",32)+padL("0.00",8));
  lines.push(rule);
  lines.push("  Cashier: STAFF");
  lines.push("  Register: ONLINE");
  lines.push("  Location: 0");
  lines.push("  Table:");
  lines.push("We appreciate your comments:");
  lines.push(center("(613) 394-3000"));
  lines.push(center("OPEN 5 DAYS A WEEK. SEE YOU AGAIN!"));

  const html=`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Prep Ticket #${t.orderNumber||t.id}</title>
<style>
  *{margin:0;padding:0;box-sizing:border-box;}
  body{font-family:'Courier New',Courier,monospace;font-size:12px;width:72mm;padding:4px 2px;background:#fff;color:#000;}
  pre{white-space:pre-wrap;word-break:break-word;line-height:1.4;}
  @media print{
    @page{size:72mm auto;margin:2mm;}
    body{width:72mm;}
    .no-print{display:none;}
  }
</style></head><body>
<div class="no-print" style="text-align:center;padding:8px 0;margin-bottom:8px;border-bottom:1px dashed #ccc;">
  <button onclick="window.print()" style="font-family:sans-serif;padding:6px 20px;background:#c09b6d;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:13px;">🖨 Print</button>
</div>
<pre>${lines.join('\n').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</pre>
</body></html>`;

  // Inject a print overlay div into the current page
  let overlay=document.getElementById('__print_overlay__');
  if(overlay) overlay.remove();
  overlay=document.createElement('div');
  overlay.id='__print_overlay__';
  overlay.style.cssText='position:fixed;inset:0;z-index:99999;background:#fff;overflow:auto;';
  overlay.innerHTML=html;
  // Add a close button
  const closeBtn=document.createElement('button');
  closeBtn.textContent='✕ Close';
  closeBtn.style.cssText='position:fixed;top:12px;right:12px;z-index:100000;font-family:sans-serif;padding:6px 14px;background:#333;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:13px;';
  closeBtn.onclick=()=>overlay.remove();
  overlay.appendChild(closeBtn);
